const body = $input.first().json.body;
const entry  = body?.entry?.[0];
const change = entry?.changes?.[0]?.value;
const message = change?.messages?.[0];
const contact = change?.contacts?.[0];

if (!message) return [{ json: { skip: true } }];

const base = {
  skip: false,
  isUnsupported: false,
  isInteractive: false,
  phoneNumber: message.from,
  phoneNumberId: change.metadata.phone_number_id,
  contactName: contact?.profile?.name || 'Student',
  timestamp: message.timestamp,
};

// Interactive list reply (student picked from menu)
if (message.type === 'interactive' && message.interactive?.type === 'list_reply') {
  const r = message.interactive.list_reply;
  return [{ json: { ...base, isInteractive: true, selectionId: r.id, selectionTitle: r.title, query: r.title } }];
}

// Interactive button reply
if (message.type === 'interactive' && message.interactive?.type === 'button_reply') {
  const r = message.interactive.button_reply;
  return [{ json: { ...base, isInteractive: true, selectionId: r.id, selectionTitle: r.title, query: r.title } }];
}

// Non-text, non-interactive
if (message.type !== 'text') {
  return [{ json: { ...base, isUnsupported: true, response: 'I only understand text messages and menu selections. Use the menu below to check your timetable.' } }];
}

return [{ json: { ...base, query: message.text.body } }];

const input = $input.first().json;
const query = (input.query || '').trim();
const queryLower = query.toLowerCase();

// Section mapping — longest keyword first to avoid short prefix collisions
const sectionMap = [
  { keywords: ['sec-sk', 'sec sk', 'section sk', 'sk'], tab: 'Sec-SK', name: 'Section SK' },
  { keywords: ['software development b', 'software dev b', 'sd b'], tab: 'CSE_SD_Sec_B',       name: 'Software Dev (Sec B)' },
  { keywords: ['software development', 'software dev', 'sd'],        tab: 'CSE_SD_Sec_A',       name: 'Software Dev (Sec A)' },
  { keywords: ['aiml b', 'ai b'],                                    tab: 'CSE_AIML_Sec_B',     name: 'AI & ML (Sec B)' },
  { keywords: ['aiml', 'ai', 'artificial intelligence', 'machine learning', 'ml'], tab: 'CSE_AIML_Sec_A', name: 'AI & ML (Sec A)' },
  { keywords: ['cyber security b', 'cybersec b', 'cyber b', 'cys b'], tab: 'CSE_CyberSec_Sec_B', name: 'Cyber Security (Sec B)' },
  { keywords: ['cyber security', 'cybersec', 'cyber', 'cys'],        tab: 'CSE_CyberSec_Sec_A', name: 'Cyber Security (Sec A)' },
  { keywords: ['ibm'],                                                tab: 'CSE_IBM_Sec_A',      name: 'IBM (Sec A)' },
  { keywords: ['xebia'],                                              tab: 'CSE_Xebia_Sec_A',   name: 'Xebia (Sec A)' },
];

let detectedSection = null;
let detectedSectionName = null;
for (const m of sectionMap) {
  if (m.keywords.some(k => queryLower.includes(k))) {
    detectedSection = m.tab;
    detectedSectionName = m.name;
    break;
  }
}

// Day detection
const dayMap = {
  'monday': 'Monday', 'mon': 'Monday',
  'tuesday': 'Tuesday', 'tue': 'Tuesday',
  'wednesday': 'Wednesday', 'wed': 'Wednesday',
  'thursday': 'Thursday', 'thu': 'Thursday',
  'friday': 'Friday', 'fri': 'Friday',
  'saturday': 'Saturday', 'sat': 'Saturday',
};

const now = new Date();
const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const todayWords = ['today', 'aaj'];
const tomorrowWords = ['tomorrow', 'kal'];
let detectedDay = null;

if (todayWords.some(w => queryLower.includes(w))) {
  detectedDay = dayNames[now.getDay()];
} else if (tomorrowWords.some(w => queryLower.includes(w))) {
  const tmp = new Date(now); tmp.setDate(tmp.getDate() + 1);
  detectedDay = dayNames[tmp.getDay()];
} else {
  for (const [key, day] of Object.entries(dayMap)) {
    if (queryLower.includes(key)) { detectedDay = day; break; }
  }
}

// fullDayRange: SheetTab!A:H — Sheets node uses this directly
const fullDayRange = detectedSection ? `${detectedSection}!A:H` : null;

return [{ json: {
  ...input,
  detectedSection,
  detectedSectionName,
  detectedDay,
  needsSection: !detectedSection,
  fullDayRange,
} }];

// Format timetable for WhatsApp — plain text + emoji
// Works for both text-query path (Query Preprocessor) and interactive path (Parse Selection)
const rows = $input.all().map(i => i.json);

let preprocessed = {};
try { preprocessed = $('Query Preprocessor').first().json; } catch(_) {
  try { preprocessed = $('Parse Selection').first().json; } catch(__) {}
}

const requestedDay = preprocessed.detectedDay;

const slots = [
  { col: 'Lecture 1 (8.00-8.50)',   time: '8:00–8:50 AM'   },
  { col: 'Lecture 2 (8.50-9.40)',   time: '8:50–9:40 AM'   },
  { col: 'Lecture 3 (9.40-10.30)',  time: '9:40–10:30 AM'  },
  { col: 'Lecture 4 (10.30-11.20)', time: '10:30–11:20 AM' },
  { col: 'Lecture 5 (11.20-12.05)', time: '11:20–12:05 PM' },
  { col: 'Lecture 6 (12.05-12.50)', time: '12:05–12:50 PM' },
];

function formatDay(row) {
  const day   = row['Day/Time'] || '';
  const lines = ['📅 *' + day + '*'];
  let lastVal = '';
  for (const slot of slots) {
    let val = (row[slot.col] || '').trim();
    if (!val && lastVal) { val = lastVal + ' (cont.)'; }
    else { lastVal = val || ''; }
    if (val && val !== 'N/A') {
      lines.push('⏰ ' + slot.time + '\n   📚 ' + val);
    } else {
      lastVal = '';
      lines.push('⏰ ' + slot.time + '\n   Free Period');
    }
  }
  return lines.join('\n');
}

let formatted = [];
if (requestedDay) {
  const dayRow = rows.find(r => r['Day/Time']?.toLowerCase() === requestedDay.toLowerCase());
  formatted.push(dayRow ? formatDay(dayRow) : 'No schedule found for ' + requestedDay + '.');
} else {
  for (const row of rows) {
    if (row['Day/Time'] && row['Day/Time'] !== 'Day/Time') formatted.push(formatDay(row));
  }
}

const label = preprocessed.detectedDay
  ? '📊 ' + preprocessed.detectedDay + ' — ' + (preprocessed.detectedSectionName || preprocessed.detectedSection || '')
  : '📊 Full Week — ' + (preprocessed.detectedSectionName || preprocessed.detectedSection || '');

return [{ json: { ...preprocessed, response: label + '\n\n' + formatted.join('\n\n') } }];

const input = $input.first().json;
return [{ json: {
  ...input,
  response: '🔒 This bot is currently in testing.\nAccess is restricted to registered users only.'
} }];

const input = $input.first().json;
const id = (input.selectionId || '').trim();

// Section selected from first menu: "SECTION|CSE_SD_Sec_A"
if (id.startsWith('SECTION|')) {
  const tab = id.replace('SECTION|', '');
  const labels = {
    'CSE_SD_Sec_A':       'Software Dev (Sec A)',
    'CSE_SD_Sec_B':       'Software Dev (Sec B)',
    'CSE_AIML_Sec_A':     'AI & ML (Sec A)',
    'CSE_AIML_Sec_B':     'AI & ML (Sec B)',
    'CSE_CyberSec_Sec_A': 'Cyber Security (Sec A)',
    'CSE_CyberSec_Sec_B': 'Cyber Security (Sec B)',
    'CSE_IBM_Sec_A':      'IBM (Sec A)',
    'CSE_Xebia_Sec_A':    'Xebia (Sec A)',
    'Sec-SK':             'Section SK',
  };
  return [{ json: {
    ...input,
    isTimestableRequest: false,
    detectedSection: tab,
    detectedSectionName: labels[tab] || tab,
    detectedDay: null,
    fullDayRange: null,
  }}];
}

// Day selected from second menu: "CSE_SD_Sec_A|Monday"
const parts = id.split('|');
if (parts.length === 2 && parts[0] && parts[1]) {
  const tab = parts[0], day = parts[1];
  const labels = {
    'CSE_SD_Sec_A':       'Software Dev (Sec A)',
    'CSE_AIML_Sec_A':     'AI & ML (Sec A)',
    'CSE_CyberSec_Sec_A': 'Cyber Security (Sec A)',
    'CSE_IBM_Sec_A':      'IBM (Sec A)',
    'CSE_Xebia_Sec_A':    'Xebia (Sec A)',
    'Sec-SK':             'Section SK',
  };
  return [{ json: {
    ...input,
    isTimestableRequest: true,
    detectedSection: tab,
    detectedSectionName: labels[tab] || tab,
    detectedDay: day,
    fullDayRange: `${tab}!A:H`,
  }}];
}

// Unrecognised — send section menu again
return [{ json: { ...input, isTimestableRequest: false, detectedSection: null, detectedSectionName: null, detectedDay: null, fullDayRange: null } }];
